{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Ketoconazole, the closest structural analogue (Morgan 0.5532), has a measured oral bioavailability of approximately 75% in healthy volunteers after a 200 mg dose, supporting high F for this azole antifungal scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Posaconazole, the next closest analogue (Morgan 0.5288), showed 56% oral bioavailability in fasted Western volunteers with a 300 mg tablet, directly supporting F ≥20% under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Posaconazole absolute bioavailability was 0.54–0.75 in patients receiving the oral suspension at 400 mg BID, providing direct absolute-F evidence above the 20% threshold for a close analogue.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is itraconazole, a triazolone azole antifungal. The closest retrieved analogues, ketoconazole and posaconazole, have measured oral bioavailability values of approximately 75% and 42–56% (fasted tablet), respectively, all above the 20% threshold. The shared azole antifungal class and structural similarity make high oral bioavailability the best-supported prediction.",
  "evidence_gaps": [
    "No direct itraconazole bioavailability record is present in the retrieved evidence; prediction relies on close analogues.",
    "The query's formulation is unspecified; azole oral bioavailability can vary by formulation, as seen with posaconazole suspension versus tablets.",
    "Fasted-state data are available for posaconazole but not directly for ketoconazole, though ketoconazole healthy-volunteer data are consistently high."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

